test('legacy desktop external offset migrates to zero without altering scientific route, active internal offsets or other contexts',async()=>{const x=await page();await method(x,'poni',Object.keys(science.analyses.poni)[0]);const reader=x.d.getElementById('np-detail-scroll'),tree=x.d.getElementById('np-tree-scroll');tree.scrollTop=143;tree.scrollLeft=37;reader.scrollTop=221;x.d.getElementById('np-node-'+x.a.getState().route.node).focus();const saved=save(x),hash=x.w.location.hash,M=x.M,state=saved[M.KEY],key=M.contextKey(state.route);state.contexts[key].windowScroll=150;const original=JSON.parse(JSON.stringify(state));await close(x);const cold=await page({hash,saved});try{assert.equal(cold.w.scrollY,0);assert.equal(cold.d.getElementById('np-tree-scroll').scrollTop,143);assert.equal(cold.d.getElementById('np-tree-scroll').scrollLeft,37);assert.equal(cold.d.getElementById('np-detail-scroll').scrollTop,221);const restored=JSON.parse(JSON.stringify(cold.a.getState()));assert.deepEqual(restored.route,original.route);assert.deepEqual(restored.originTrail,original.originTrail);for(const context of Object.keys(original.contexts))if(context!==key)assert.deepEqual(restored.contexts[context],original.contexts[context]);assert.equal(restored.contexts[key].windowScroll,150,'legacy saved offset is not a license to clear state');assert.deepEqual(restored.contexts[key].treeScrollByTree,original.contexts[key].treeScrollByTree);save(cold);assert.equal(cold.M.getBucket(cold.a.getState()).windowScroll,0);cold.M.validateState(cold.a.getBundle(),cold.a.getState());}finally{await close(cold);}});

