// CSSOM declaration regression only; actual 132px/752px geometry stays in Chrome CI.
test('desktop panels explicitly remove the legacy five-pixel margin without changing narrow layout',()=>{
 const css=fs.readFileSync(path.join(root,'assets/navigation-product.css'),'utf8'),dom=new JSDOM('<style></style>');
 try {
  const style=dom.window.document.querySelector('style');style.textContent=css;
  const rules=[...style.sheet.cssRules],legacy=rules.find(r=>r.selectorText==='.np-panels'&&r.style.getPropertyValue('margin-top')==='5px');
  assert.ok(legacy,'the existing non-desktop declaration is retained');
  const desktop=rules.filter(r=>r.media&&/^\(min-width:\s*1200px\)$/.test(r.media.mediaText)).flatMap(r=>[...r.cssRules]);
  const panels=desktop.filter(r=>r.selectorText==='#navigation-product .np-panels');assert.equal(panels.length,1,'one explicit desktop shell panel rule');
  const assertDesktop=()=>{assert.match(panels[0].style.getPropertyValue('margin-top'),/^0(?:px)?$/,'desktop shell must neutralize the legacy margin');assert.equal(legacy.style.getPropertyValue('margin-top'),'5px');};
  assertDesktop();
  panels[0].style.removeProperty('margin-top');assert.throws(assertDesktop,/neutralize the legacy margin/,'omitting the override recreates the real five-pixel displacement');
  panels[0].style.setProperty('margin-top','5px');assert.throws(assertDesktop,/neutralize the legacy margin/,'retaining five pixels cannot pass the approved zero-margin contract');
  panels[0].style.setProperty('margin-top','0');assertDesktop();
 } finally {dom.window.close();}
});

// Identity-dedup display contract: only exact generated summary identity wrappers
// share the fixed desktop heading. Scientific evidence and every A answer remain.
const duplicateClass='np-reader-identity-duplicate';
function globalEntityPosition(x,id){const rows=Object.values(x.a.getBundle().researchMap.positions).filter(p=>p.entityId===id);assert.equal(rows.length,1,id+' has one original global position');return rows[0];}
async function selectIdentityPosition(x,p){await go(x,x.M.routeForPosition(x.a.getBundle(),{scope:p.scopeId||'scope:all'},p.id));assert.equal(x.a.getState().route.node,p.id);assert.equal(x.a.getState().route.version,p.versionId||null);}
function questionBlock(x,p){const section=x.d.querySelector('#np-reader-summary [data-reading-node="'+p.id+'"]');assert.ok(section);return [...section.querySelectorAll(':scope > .np-detail-block')].find(n=>n.querySelector('h3')?.textContent==='研究问题');}
function assertMarkedIdentity(x,node,p,text){assert.ok(node);assert.ok(node.classList.contains(duplicateClass));assert.equal(node.dataset.readerDuplicatePosition,p.id);assert.equal(node.hidden,false,'no permanent hidden attribute replaces the desktop-only CSS');assert.equal(x.d.getElementById('np-reader-object-title').dataset.objectPosition,p.id);assert.equal(x.d.getElementById('np-reader-object-title').dataset.objectEntity,p.entityId);assert.equal(x.d.querySelector('#np-reader-object-title > h2').textContent,text);assert.equal(node.closest('#np-reader-summary'),x.d.getElementById('np-reader-summary'));}
function assertScientificBlockUnmarked(node){assert.ok(node);assert.equal(node.closest('.'+duplicateClass),null);assert.equal(node.querySelector('.'+duplicateClass),null);assert.equal(node.hidden,false);}

