test('identity dedup: desktop peer CSSOM rejects missing overrides and legacy nested scrolling or nowrap regressions',()=>{
 const css=fs.readFileSync(path.join(root,'assets/navigation-product.css'),'utf8'),dom=new JSDOM('<style></style>');try{
  const style=dom.window.document.querySelector('style');style.textContent=css;const rules=[...style.sheet.cssRules],legacy=rules.find(rule=>rule.selectorText==='.np-peer-strip'&&rule.style.getPropertyValue('overflow-x')==='auto');assert.ok(legacy,'narrow-width legacy peer scrolling is retained');
  function desktopRules(selector){return [...style.sheet.cssRules].filter(rule=>rule.media&&/^\(min-width:\s*1200px\)$/.test(rule.media.mediaText)).flatMap(group=>[...group.cssRules].map((rule,index)=>({group,rule,index}))).filter(({rule})=>rule.selectorText===selector);}
  function assertDesktop(){const rows=desktopRules('#navigation-product .np-peer-strip');assert.equal(rows.length,1,'one desktop peer override is required');const declaration=rows[0].rule.style;for(const [key,value] of [['flex-wrap','wrap'],['overflow','visible'],['white-space','normal'],['min-width','0']])assert.equal(declaration.getPropertyValue(key),value,'desktop peer '+key+' must avoid an extra scrolling surface');const buttons=desktopRules('#navigation-product .np-peer-strip button').filter(({rule})=>rule.style.getPropertyValue('flex'));assert.equal(buttons.length,1);for(const [key,value] of [['flex','0 1 auto'],['max-width','100%'],['min-width','0'],['white-space','normal'],['overflow-wrap','anywhere']])assert.equal(buttons[0].rule.style.getPropertyValue(key),value);assert.equal(legacy.style.getPropertyValue('overflow-x'),'auto','narrow peer behavior is unchanged');}
  assertDesktop();for(const [property,value] of [['overflow',null],['overflow','auto'],['white-space','nowrap'],['flex-wrap','nowrap']]){const declaration=desktopRules('#navigation-product .np-peer-strip')[0].rule.style,original=declaration.cssText;try{if(value===null)declaration.removeProperty(property);else declaration.setProperty(property,value);assert.throws(assertDesktop,/desktop peer .*must avoid an extra scrolling surface/,'the old nested strip must not pass');}finally{declaration.cssText=original;}assertDesktop();}
  const entry=desktopRules('#navigation-product .np-peer-strip')[0],original=entry.rule.cssText;entry.group.deleteRule(entry.index);assert.throws(assertDesktop,/one desktop peer override is required/,'deleting the desktop override recreates the regression');entry.group.insertRule(original,entry.index);assertDesktop();
 }finally{dom.window.close();}
});

// CSSOM/cascade regression only; the real Chrome capture keeps its strict 4.5 gate.
test('desktop research-question role inherits readable metadata color instead of the legacy last-child tint',()=>{
 const css=fs.readFileSync(path.join(root,'assets/navigation-product.css'),'utf8'),selector='#np-reader-object-meta .np-reader-field-role';
 function contrast(rgb){const linear=rgb.map(v=>v/255).map(v=>v<=0.04045?v/12.92:((v+0.055)/1.055)**2.4);return 1.05/(linear[0]*0.2126+linear[1]*0.7152+linear[2]*0.0722+0.05);}
 for(const width of [1440,1920]){
  const dom=new JSDOM('<style></style><div id="navigation-product"><div class="np-reader-heading"><p id="np-reader-object-meta">困难 · 未固定论文版本<span class="np-reader-field-role" data-reader-field-role="plain_language_question"> · 研究问题</span></p></div></div>');
  try {
   const w=dom.window,style=w.document.querySelector('style'),role=w.document.querySelector('.np-reader-field-role');style.textContent=css;
   const entries=[];function collect(rules,media=[]){for(const rule of rules)if(rule.media)collect(rule.cssRules,media.concat(rule.media.mediaText));else if(rule.selectorText)entries.push({rule,media});}collect(style.sheet.cssRules);
   const overrides=entries.filter(({rule})=>rule.selectorText===selector&&rule.style.getPropertyValue('color'));assert.equal(overrides.length,1);assert.deepEqual(overrides[0].media,['(min-width:1200px)']);assert.equal(overrides[0].rule.style.getPropertyValue('color'),'inherit');assert.equal(overrides[0].rule.style.getPropertyValue('display'),'inline');
   const legacy=entries.find(({rule})=>rule.selectorText==='.np-reader-heading span:last-child');assert.ok(legacy);assert.ok(role.matches(legacy.rule.selectorText),'the actual last-child span triggers the historical rule');assert.ok(role.matches(selector));assert.equal(legacy.rule.style.getPropertyValue('color'),'#6c838b');assert.ok(selector.startsWith('#np-reader-object-meta '));assert.equal(legacy.rule.selectorText.includes('#'),false,'the exact local ID selector outranks the legacy class/pseudo-class rule');
   // JSDOM does not apply viewport media queries. Materialize only the current
   // screen-width rules in their original order; this is not a pixel assertion.
   function active(media){return media.every(query=>{const match=query.match(/^\((min|max)-width:\s*(\d+)px\)$/);if(match)return match[1]==='min'?width>=Number(match[2]):width<=Number(match[2]);assert.ok(['print','(prefers-reduced-motion:reduce)'].includes(query),'explicitly account for every other media condition');return false;});}
   const flattened=entries.filter(({media})=>active(media)).map(({rule})=>rule.cssText).join('\n');
   function install(value){style.textContent=flattened;const rule=[...style.sheet.cssRules].find(rule=>rule.selectorText===selector&&rule.style.getPropertyValue('color'));if(value===null)rule.style.removeProperty('color');else rule.style.setProperty('color',value);style.textContent=[...style.sheet.cssRules].map(rule=>rule.cssText).join('\n');}
   // cssstyle returns the keyword for explicit inherit, so resolve it through
   // the actual parent's computed color rather than inventing a fallback color.
   function rgb(node){const value=w.getComputedStyle(node).color;if(value==='inherit')return rgb(node.parentElement);const match=value.match(/^rgb\((\d+),\s*(\d+),\s*(\d+)\)$/);assert.ok(match,value);return match.slice(1).map(Number);}
   function readable(){assert.deepEqual(rgb(role),rgb(role.parentElement),'field role must use its metadata parent color');assert.ok(contrast(rgb(role))>=4.5,'field role must meet the unchanged 4.5:1 contrast floor on white');}
   install('inherit');assert.deepEqual(rgb(role.parentElement),[86,102,92]);readable();
   install(null);assert.deepEqual(rgb(role),[108,131,139]);assert.ok(contrast(rgb(role))<4.5);assert.throws(readable,/metadata parent color/,'omitting the local override recreates the measured Chrome contrast failure');
   install('#6c838b');assert.deepEqual(rgb(role),[108,131,139]);assert.ok(contrast(rgb(role))<4.5);assert.throws(readable,/metadata parent color/,'explicitly restoring the old tint also fails');
   install('inherit');readable();assert.equal(role.textContent,' · 研究问题');assert.equal(role.dataset.readerFieldRole,'plain_language_question');
  } finally {dom.window.close();}
 }
});

// Method-reading is a desktop projection of original positions, not a route or
// scientific-parent migration. These tests cannot establish pixel geometry.
const methodCases={g:'pos:g:b3c94b96a7de2feaa05e57',l:'pos:l:ff0298ffa17b4cfcf009bd',poni:'pos:l:98bc421b8bfd17d6699922',rich:'pos:l:2375b80624416660370c06',conditional:'pos:l:6dfcd92715fbf884c850ce'};
const plain=value=>JSON.parse(JSON.stringify(value));
function methodSourceText(value){if(value==null)return '';if(typeof value==='string'||typeof value==='number')return String(value).replace(/\\n/g,'\n');if(Array.isArray(value))return value.map(methodSourceText).filter(Boolean).join('；');return methodSourceText(value.text||value.value||value.description||value.statement||'');}
function methodVersion(bundle,p){const v=bundle.versions[p.versionId];return v&&(v.label||v.descriptor)||p.versionId;}
function methodNode(x,id){const node=x.d.getElementById('np-node-'+id);assert.ok(node,'original tree position '+id);return node;}
function methodRoute(x,p){return x.M.routeForPosition(x.a.getBundle(),{scope:p.scopeId||'scope:all'},p.id);}
function methodItems(x){return [...x.d.querySelectorAll('#np-tree [role=treeitem]')];}
function methodRoving(x,id){const rows=methodItems(x);assert.equal(rows.filter(n=>n.tabIndex===0).length,1,'one roving focus target in the projected main tree');if(id)assert.equal(rows.find(n=>n.tabIndex===0).dataset.position,id);for(const button of x.d.querySelectorAll('#np-tree [role=treeitem] > .np-node-row button'))assert.equal(button.tabIndex,-1,'tree row controls cannot add separate Tab stops');}
function methodKey(x,node,key){const event=new x.w.KeyboardEvent('keydown',{key,bubbles:true,cancelable:true});node.dispatchEvent(event);return event;}
function assertMethodProjection(x,p){
 const b=x.a.getBundle(),ancestors=Array.from(x.M.ancestors(b,p.id)),pathIds=ancestors.concat(p.id),rows=methodItems(x),expanded=new Set(x.M.getBucket(x.a.getState()).expandedByTree[p.tree]),expected=pathIds.slice();
 function descendants(id){for(const child of b.positions[id].childIds){expected.push(child);if(expanded.has(child))descendants(child);}}if(expanded.has(p.id))descendants(p.id);
 assert.equal(x.d.getElementById('navigation-product').dataset.methodReading,'true');assert.equal(x.d.getElementById('navigation-product').dataset.readingLayout,'reading');assert.equal(x.d.getElementById('np-tree-heading').textContent,'当前位置与来路');assert.deepEqual(rows.map(n=>n.dataset.position),expected,'only the actual ancestor path and normally expanded original children are tree items');
 for(const [index,id] of pathIds.entries()){
  const q=b.positions[id],node=methodNode(x,id);assert.equal(node.dataset.parent,q.parentId||'');assert.equal(node.dataset.tree,p.tree);assert.equal(node.dataset.entity,q.entityId);assert.equal(node.dataset.association,q.association||'');assert.equal(node.dataset.displayRole,q.displayRole||'');assert.equal(Number(node.getAttribute('aria-level')),index+1);assert.equal(node.querySelector(':scope > .np-node-row > .np-node-label').title,q.sourceLabel||q.label);
  assert.equal(node.dataset.methodAncestor,index<ancestors.length?'true':undefined);assert.equal(node.getAttribute('aria-selected'),String(id===p.id));const domParent=node.parentElement.closest('[role=treeitem]');assert.equal(domParent?.dataset.position||null,q.parentId||null,'every displayed parent edge is original');if(index<ancestors.length){assert.equal(node.getAttribute('aria-expanded'),'true');assert.deepEqual([...node.querySelectorAll(':scope > [role=group] > [role=treeitem]')].map(n=>n.dataset.position),[pathIds[index+1]],'ancestor renders its actual path child, not a fabricated grouping');}
 }
 for(const node of rows){const q=b.positions[node.dataset.position];assert.ok(q);assert.equal(q.tree,p.tree);assert.equal(q.scopeId,p.scopeId);assert.equal(Number(node.getAttribute('aria-level')),x.M.ancestors(b,q.id).length+1);const peers=[...node.parentElement.children].filter(n=>n.getAttribute('role')==='treeitem');assert.equal(Number(node.getAttribute('aria-posinset')),peers.indexOf(node)+1);assert.equal(Number(node.getAttribute('aria-setsize')),peers.length);}
 methodRoving(x);return {ancestors,pathIds,rows};
}
function assertMethodSiblings(x,p){
 const b=x.a.getBundle(),parent=b.positions[p.parentId],ids=parent?Array.from(parent.childIds).filter(id=>id!==p.id):[],groups=[...x.d.querySelectorAll('details[data-method-siblings]')],buttons=[...x.d.querySelectorAll('button[data-method-sibling]')];
 assert.equal(groups.length,ids.length?1:0,'no siblings or alternative methods are manufactured');assert.deepEqual(buttons.map(button=>button.dataset.methodSibling),ids,'all and only other real-parent children, in original order');
 if(!ids.length)return null;const group=groups[0];assert.equal(group.dataset.methodSiblings,p.parentId);assert.equal(group.open,false);assert.ok(group.querySelector(':scope > summary').textContent.includes(String(ids.length)));assert.equal(group.querySelector('[role=tree],[role=treeitem],[data-position]'),null,'the navigation disclosure does not claim a scientific group or parent');
 for(const [index,button] of buttons.entries()){const q=b.positions[ids[index]],source=q.sourceLabel||q.label;assert.equal(button.disabled,false);assert.equal(button.tabIndex,0);assert.equal(button.closest('[role=treeitem]'),null,'native peer button is outside the ARIA tree');assert.ok(button.textContent.includes(source),'complete original sibling label '+q.id);if(q.versionId)assert.ok(button.textContent.includes(methodVersion(b,q)),'exact sibling source version '+q.id);if(q.displayRole)assert.ok(button.textContent.includes(q.displayRole));assert.equal(q.parentId,p.parentId);assert.equal(q.tree,p.tree);assert.equal(q.scopeId,p.scopeId);assert.equal(x.d.getElementById('np-node-'+q.id),null,'sibling navigation never becomes a projected descendant');}
 return group;
}
