test('desktop method reading: sibling history restores open disclosure geometry before clamped tree offsets',async t=>{
 const x=await page();t.after(()=>close(x));const b=x.a.getBundle(),p=b.positions[methodCases.poni];await selectMethodExact(x,p);
 const tree=x.d.getElementById('np-tree-scroll'),reader=x.d.getElementById('np-detail-scroll');let effective=0,clamped=false;
 Object.defineProperty(tree,'scrollTop',{configurable:true,get:()=>effective,set:value=>{const details=x.d.querySelector('details[data-method-siblings]'),limit=details&&details.open?500:10;effective=Math.max(0,Math.min(Number(value)||0,limit));if(Number(value)>limit)clamped=true;}});
 for(const mode of ['history','explicit']){
  if(x.a.getState().route.node!==p.id)await selectMethodExact(x,p);
  const details=x.d.querySelector('details[data-method-siblings]');details.querySelector(':scope > summary').click();assert.equal(details.open,true);
  const button=details.querySelector('[data-method-sibling]'),id=button.id;button.focus();tree.scrollTop=220;tree.scrollLeft=17;reader.scrollTop=229;const before=plain(save(x)[x.M.KEY]);assert.equal(tree.scrollTop,220);button.click();await ready(x);assert.notEqual(x.a.getState().route.node,p.id);clamped=false;
  if(mode==='history'){x.w.history.back();await wait(60);await ready(x);}else{x.d.querySelector('#np-origin-trail .np-return-previous').click();await ready(x);}
  assert.deepEqual(plain(x.a.getState().route),before.route);assert.deepEqual(plain(x.a.getState().originTrail),before.originTrail);assert.equal(x.d.activeElement.id,id);assert.equal(x.d.activeElement.closest('details').open,true);assert.equal(tree.scrollTop,220,'effective offset must survive closed-details browser clamp');assert.equal(tree.scrollLeft,17);assert.equal(reader.scrollTop,229);assert.equal(clamped,false,'restore cannot apply saved offset before opening its exact focused disclosure');
  const restored=x.d.activeElement.closest('details');restored.open=false;tree.scrollTop=220;assert.equal(tree.scrollTop,10,'negative fixture models the browser clamp when disclosure is closed');restored.open=true;tree.scrollTop=220;
  if(mode==='history'){x.w.history.forward();await wait(60);await ready(x);await selectMethodExact(x,p);}else restored.open=false;
 }
});

