// S0 footer owns normal-flow desktop space; geometry is verified in real Chrome.
function s0FooterSource(x){
 const b=x.a.getBundle(),p=b.positions,root=p[b.researchMap.roots[0]],l=p[root.childIds.find(id=>p[id].entityId==='legacy:nav:l')],c=p[root.childIds.find(id=>p[id].entityId==='legacy:nav:c')],tasks=p[l.childIds.find(id=>p[id].sourceDirectoryGroupId==='task')],scopes=tasks.childIds.map(id=>b.scopes.find(s=>s.id===p[id].sourceScopeId));
 assert.ok(scopes.every(Boolean));function counts(field){return scopes.reduce((o,s)=>{const cv=s.coverage||{};o[cv.direct&&cv.direct[field]?'direct':cv.condition&&cv.condition[field]?'condition':'gap']++;return o;},{direct:0,condition:0,gap:0});}const mc=counts('methodCount'),cc=counts('challengeCount');
 return {positions:[root.id,l.id,c.id,tasks.id,...tasks.childIds,...c.childIds],taskIds:tasks.childIds,challengeIds:c.childIds,coverage:'当前方法：'+mc.direct+'个入口直接关联、'+mc.condition+'个仅条件关联、'+mc.gap+'个未整理；CI：'+cc.direct+'个直接关联、'+cc.condition+'个仅条件关联、'+cc.gap+'个未整理。选段覆盖，不代表全文精读或领域穷尽。'};
}
