// These measured-size fixtures exercise layout arithmetic, not browser pixels.
// Real node/card bounds, text visibility and exposed SVG strokes remain Chrome gates.
const spacingController=fs.readFileSync(path.join(root,'assets/navigation-product.js'),'utf8');
const spacingFunction=Function(spacingController.match(/^function overviewVerticalSpacing\([^]*?^\}/m)[0]+';return overviewVerticalSpacing;')();
const spacingPlacement=Function('return '+spacingController.match(/var OVERVIEW_TASK_PLACEMENT=(\{[^]*?\n\});/)[1])();
test('S0 adaptive spacing: actual compact extent and actual row counts bound spare-space allocation',()=>{
 const positions={a:{y:0,h:40},b:{y:600,h:49}},before=plain(positions);
 for(const [height,rows,challenges,expected] of [[659,6,13,{task:0,challenge:0}],[661,6,13,{task:0,challenge:0}],[691,6,13,{task:6,challenge:2.5}],[839,6,13,{task:24,challenge:7}],[691,3,4,{task:15,challenge:7}],[691,0,1,{task:0,challenge:0}],[400,6,13,{task:0,challenge:0}]])assert.deepEqual(spacingFunction(height,positions,rows,challenges),expected);
 assert.deepEqual(positions,before,'allocation cannot mutate measured compact inputs');assert.deepEqual(spacingFunction(691,{a:{y:600,h:79}},6,13),{task:0,challenge:0},'actual taller content consumes spare space');
});
function spacingFixture(x){
 const map=x.d.getElementById('np-overview-map');for(const node of map.querySelectorAll('[data-map-position]')){const height=node.matches('[data-task-open]')?56:node.matches('[data-challenge-open]')?37:node.matches('[data-overview-entity]')?42.390625:node.matches('[data-reading-branch]')?37.390625:26.5;node.getBoundingClientRect=()=>({x:parseFloat(node.style.left),y:parseFloat(node.style.top),width:parseFloat(node.style.width),height:parseFloat(node.style.height)||height});}
 for(const note of map.querySelectorAll('[data-layout-note]'))note.getBoundingClientRect=()=>({height:21});
 return async(width,height,mapWidth=width-82)=>{Object.defineProperty(x.w,'innerWidth',{value:width,configurable:true});Object.defineProperty(map,'clientWidth',{value:mapWidth,configurable:true});Object.defineProperty(map,'clientHeight',{value:height,configurable:true});x.w.dispatchEvent(new x.w.Event('resize'));await frames(x.w);return spacingSnapshot(x);};
}
function spacingSnapshot(x){return [...x.d.querySelectorAll('#np-overview-map [data-map-position]')].map(n=>({id:n.dataset.mapPosition,parent:n.dataset.mapParent||null,scope:n.dataset.taskOpen||null,challenge:!!n.dataset.challengeOpen,x:parseFloat(n.style.left),y:parseFloat(n.style.top),w:parseFloat(n.style.width),h:n.getBoundingClientRect().height,minHeight:n.style.minHeight}));}
function assertSpacingSnapshot(x,actual,compact,taskExtra,challengeExtra,height){
 const source=s0FooterSource(x),rows=[...new Set(compact.filter(n=>n.scope).map(n=>spacingPlacement[n.scope][1]))].sort((a,b)=>a-b);assert.deepEqual(actual.map(n=>n.id),compact.map(n=>n.id));assert.deepEqual(actual.map(n=>n.id).sort(),source.positions.slice().sort());
 for(const node of actual){const old=compact.find(n=>n.id===node.id),rank=node.scope?rows.indexOf(spacingPlacement[node.scope][1]):node.challenge?source.challengeIds.indexOf(node.id):0,extra=node.scope?taskExtra:node.challenge?challengeExtra:0;assert.ok(Math.abs(node.y-(old.y+rank*extra))<0.00001,'exact source-ranked vertical position '+node.id);for(const key of ['parent','scope','challenge','x','w','h','minHeight'])assert.equal(node[key],old[key],'unchanged '+key+' '+node.id);assert.ok(node.y+node.h<=height,'no node crosses map/footer boundary');}
 for(let i=0;i<actual.length;i++)for(let j=i+1;j<actual.length;j++){const a=actual[i],b=actual[j];assert.ok(Math.min(a.x+a.w,b.x+b.w)<=Math.max(a.x,b.x)||Math.min(a.y+a.h,b.y+b.h)<=Math.max(a.y,b.y),'distinct node boxes never overlap');}
}
function spacingPathEnds(d){const values=d.match(/[MHV]|-?\d+(?:\.\d+)?(?:e[+-]?\d+)?/gi);let i=0,x,y,first;while(i<values.length){const op=values[i++];if(op==='M'){x=Number(values[i++]);y=Number(values[i++]);first={x,y};}else if(op==='H')x=Number(values[i++]);else if(op==='V')y=Number(values[i++]);else throw Error('unexpected route '+op);}return [first,{x,y}];}
function assertSpacingEdges(x,snapshot){
 const map=x.d.getElementById('np-overview-map'),source=s0FooterSource(x),positions=Object.fromEntries(snapshot.map(n=>[n.id,n]));function onBoundary(point,node){assert.ok(point.x>=node.x-0.001&&point.x<=node.x+node.w+0.001&&point.y>=node.y-0.001&&point.y<=node.y+node.h+0.001);assert.ok([point.x-node.x,point.x-node.x-node.w,point.y-node.y,point.y-node.y-node.h].some(v=>Math.abs(v)<0.001),'actual final node boundary');}
 const parents=[...map.querySelectorAll('path[data-map-parent]')];assert.equal(parents.length,source.positions.filter(id=>positions[x.a.getBundle().positions[id].parentId]).length);for(const p of parents){assert.equal(x.a.getBundle().positions[p.dataset.mapChild].parentId,p.dataset.mapParent);const [a,b]=spacingPathEnds(p.getAttribute('d'));onBoundary(a,positions[p.dataset.mapParent]);onBoundary(b,positions[p.dataset.mapChild]);}
 const relations=[...map.querySelectorAll('path[data-map-relation]')],triggers=[...x.d.querySelectorAll('[data-relation-select]')];assert.deepEqual(relations.map(n=>n.dataset.mapRelation),triggers.map(n=>n.dataset.relationSelect));for(const p of relations){const [a,b]=spacingPathEnds(p.getAttribute('d'));onBoundary(a,snapshot.find(n=>n.scope===p.dataset.fromEntity));onBoundary(b,snapshot.find(n=>n.scope===p.dataset.toEntity));}
}
